mapper.update:
UPDATE analysis_interviews
SET status = 'PENDING', error_code = NULL, updated_at = #{now}
WHERE id = #{id} AND status = 'FAILED'

UPDATE analysis_interviews
SET status = 'PENDING', regenerations = regenerations + 1, error_code = NULL, updated_at = #{now}
WHERE id = #{id} AND status = 'DONE' AND regenerations < #{max}

UPDATE analysis_interviews
SET status = 'DONE', error_code = NULL, generated_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND status = 'PENDING'

UPDATE analysis_interviews
SET status = 'FAILED', error_code = #{errorCode}, updated_at = #{now}
WHERE id = #{id} AND status = 'PENDING'

UPDATE analysis_interviews
SET status = 'FAILED', error_code = #{errorCode}, updated_at = #{now}
WHERE status = 'PENDING'

